gx0: {level: "B2", goals: ["أخمّن الماضي بـ Futur II.", "أفرّق بين التخمين والتأكيد."], what: "Futur II للتخمين الماضي: werden + Partizip II + haben/sein: Er wird die Mail gelesen haben (لا بدّ أنه قرأها).", why: "التخمين المهذّب أساس التقارير والاجتماعات.", when: ["تخمين: Er wird es vergessen haben.", "ضرورة ماضية: Sie muss krank gewesen sein.", "ترجيح: Das dürfte stimmen."], how: ["1- werden + Partizip II + haben/sein.", "2- Modalverb + Infinitiv II للدرجات.", "3- المتطلّب المسبق: Partizip II."], examples: [["Er wird die Mail gelesen haben.", "لا بدّ أنه قرأ الرسالة.", ""], ["Sie muss krank gewesen sein.", "لا بدّ أنها كانت مريضة.", ""]], daily: [["Er dürfte schon da sein.", "مرجّح أنه هناك.", ""]], notes: ["dürfte = مرجّح.", "könnte = محتمَل أضعف."], mistakes: [{w: "Er hat es sicher gelesen. (تخمين)", r: "Er wird es gelesen haben.", why: "التخمين الماضي بـ Futur II لا الحاضر."}], compare: "تأكيد (hat gelesen) ← تخمين (wird gelesen haben). قارن درس Konjunktiv II في K18.", summary: "تخمين الماضي = Futur II.", drill: [{t: "أي جملة تخمّن ماضيًا؟", opts: ["Er liest die Mail gerade.", "Er wird die Mail gelesen haben.", "Er wird die Mail morgen lesen."], correct: 1, why: "Futur II يخمّن الماضي."}], review: {rule: "التخمين الماضي بـ Futur II.", words: "wird, gewesen, dürfte", example: "Er wird es gelesen haben.", mistake: "الحاضر للتخمين.", q: "خمّن: أين هو؟ (وصل أمس)."}, relWords: ["Datensatz", "Messwert", "Forschungsfrage"]},
