gx2: {level: "B2", goals: ["أدمج حرف الجر مع الضمير.", "أفرّق بين العاقل وغيره."], what: "لغير العاقل: darauf, davon, dabei, worauf, wovon. للعاقل: auf ihn, von ihr.", why: "الدمج الخاطئ للعاقل خطأ فادح.", when: ["انتظار: Ich warte darauf.", "سؤال: Worauf wartest du?", "نفي: Davon weiß ich nichts."], how: ["1- غير عاقل ← ادمج.", "2- عاقل ← حرف + ضمير.", "3- wo للسؤال."], examples: [["Ich warte seit Monaten darauf.", "أنتظر ذلك منذ شهور.", ""], ["Worauf stützt sich die These?", "على ماذا تستند الفرضية؟", ""]], daily: [["Davon hängt alles ab.", "يتوقّف كل شيء على ذلك.", ""]], notes: ["da(r) + حرف لغير العاقل.", "العاقل لا يُدمج أبدًا."], mistakes: [{w: "Ich warte darauf. (لشخص)", r: "Ich warte auf ihn.", why: "العاقل: حرف + ضمير."}], compare: "عاقل (auf ihn) ← غير عاقل (darauf). قارن درس الموصول + حرف في K15.", summary: "غير العاقل يُدمج.", drill: [{t: "لغير العاقل مع auf:", opts: ["darauf", "auf ihn", "auf es"], correct: 0, why: "غير العاقل يُدمج."}], review: {rule: "الضمائر الظرفية.", words: "darauf, davon, worauf", example: "Ich warte darauf.", mistake: "الدمج للعاقل.", q: "ادمج: warte auf + ذلك."}, relWords: ["Forschungslücke", "Förderantrag", "Datenlage"]},
