gx14: {level: "B2", goals: ["أبني الكلمات باللواحق.", "أنفي بـ un- لا nicht."], what: "un-/miss- للنفي (unfair)، -heit/-keit/-ung/-schaft للأسماء (Gerechtigkeit)، -los/-voll للصفات، -bar/-lich للإمكان (machbar)، -ieren للأفعال (ratifizieren).", why: "تخمين المعنى من البنية مهارة B2.", when: ["نفي: unfair, missverstehen.", "أسماء: Gerechtigkeit, Partnerschaft.", "إمكان: machbar, erklärlich."], how: ["1- حدّد الجذر.", "2- أضف اللاحقة.", "3- راقب تغيّر المعنى."], examples: [["Aus fair wird schnell unfair.", "من العادل يصبح الجائر بسرعة.", ""], ["Subventionieren kommt von Subvention.", "يدعم مشتقّ من الدعم.", ""]], daily: [["Machbar bedeutet, man kann es machen.", "قابل للتنفيذ يعني إمكان فعله.", ""]], notes: ["un- للنفي المباشر.", "-bar = قابل لـ."], mistakes: [{w: "unmöglich nicht gelten", r: "unmöglich gelten", why: "un- تكفي بلا nicht."}], compare: "تركيب (Kompositum) ← اشتقاق (Derivation). قارن درس المركّبات.", summary: "الجذر + اللاحقة.", drill: [{t: "نفي fair باللاحقة:", opts: ["nichtfair", "fairlos", "unfair"], correct: 2, why: "un- للنفي."}], review: {rule: "الاشتقاق.", words: "un-, -heit, -bar, -ieren", example: "unfair", mistake: "nicht + منفي.", q: "اشتقّ اسمًا من gerecht."}, relWords: ["Freihandelsabkommen", "Zollschranke", "Mindeststeuersatz"]},
gx15: {level: "B2", goals: ["أتجنّب المبني للمجهول.", "أستخدم lassen و -bar و man."], what: "sich lassen + مصدر: Das lässt sich machen. و-bar/-lich: machbar. وman: Man regelt das so. وsein + zu مراجعة.", why: "البدائل أخفّ وأكثر طبيعية.", when: ["إمكان: Das lässt sich ändern.", "صفة: Der Text ist leicht zu lesen.", "عام: Man regelt das vor Ort."], how: ["1- lassen + مصدر لا Partizip.", "2- -bar للصفات.", "3- man للعموم."], examples: [["Das lässt sich leicht ändern.", "يمكن تغيير ذلك بسهولة.", ""], ["Der Antrag ist schnell zu lesen.", "الطلب سريع القراءة.", ""]], daily: [["Man regelt das vor Ort.", "يُنظَّم ذلك محليًا.", ""]], notes: ["lassen + مصدر.", "-bar للإمكان."], mistakes: [{w: "Das lässt sich gemacht.", r: "Das lässt sich machen.", why: "lassen + مصدر لا Partizip."}], compare: "مجهول (wird gemacht) ← بديل (lässt sich machen). قارن درس Passiv في K15.", summary: "بدائل Passiv.", drill: [{t: "البديل الصحيح:", opts: ["Das lässt sich gemacht.", "Das lässt sich machen.", "Das lässt machen sich."], correct: 1, why: "lassen + مصدر."}], review: {rule: "بدائل المجهول.", words: "lassen, -bar, man", example: "lässt sich machen", mistake: "Partizip بعد lassen.", q: "أعد: يمكن قراءته بسهولة."}, relWords: ["Emissionshandel", "CO2-Bepreisung", "Welthandel"]}
